im = Image.open('radiograph.jpg').convert('L')
def crop(box,name,scale):
    c=im.crop(box).resize((int((box[2]-box[0])*scale),int((box[3]-box[1])*scale)), Image.LANCZOS)
    c=c.filter(ImageFilter.UnsharpMask(radius=4, percent=110, threshold=2))
